import {describe, it, expect} from '@jest/globals';
import {ToolRegistry} from './registry.js';

describe('Reproduction', () => {
  it('should include property name in error message', async () => {
    const registry = new ToolRegistry();
    registry.register(
      {
        name: 'test-tool',
        description: 'desc',
        inputSchema: {
          type: 'object',
          properties: {
            val: {type: 'string'},
          },
        },
      },
      async () => 'ok'
    );

    const response = await registry.execute('test-tool', {val: 123});
    console.log('Error result:', response.result);
    expect(response.result).toContain('val');
  });
});

